export const rewardRedemptionDefinitions={
 rewardRedemption:{title:'Compare a matched cash purchase with redeeming and buying any missing points',fields:[
  ['cashPrice','All-in price of the matched cash alternative (CAD)',600,0,5000,25],
  ['requiredPoints','Points required for the redemption',30000,1000,200000,1000],
  ['ownedPoints','Existing points available before this decision',15000,0,300000,1000],
  ['redemptionCash','Mandatory cash payment when redeeming (CAD)',100,0,2000,10],
  ['purchaseCents','All-in cost to buy each missing point (cents per point)',1.5,0,10,.1],
  ['alternativeCents','Chosen alternative-use value of each existing point consumed (cents)',1,0,10,.1]
 ]}
};
export function rewardRedemptionCost(input) {
 const ownedUsed=Math.min(input.ownedPoints,input.requiredPoints),missing=Math.max(0,input.requiredPoints-input.ownedPoints),pointPurchase=missing*input.purchaseCents/100;
 const cashOutlay=input.redemptionCash+pointPurchase,cashSaved=input.cashPrice-cashOutlay,ownedValue=ownedUsed*input.alternativeCents/100;
 return {ownedUsed,missing,pointPurchase,cashOutlay,cashSaved,ownedValue,netComparison:cashSaved-ownedValue,impliedCents:(input.cashPrice-input.redemptionCash)/input.requiredPoints*100,pointsLeft:Math.max(0,input.ownedPoints-input.requiredPoints)};
}
export function rewardRedemptionResult(kind,input) {
 if(kind!=='rewardRedemption')throw Error('Unknown reward-redemption topic.');
 const p=rewardRedemptionCost(input),cashRange=Array.from({length:21},(_,i)=>{const x=i*Math.max(1000,input.cashPrice*1.5)/20;return {x,value:rewardRedemptionCost({...input,cashPrice:x}).impliedCents};});
 return {metrics:[['Cash paid to redeem, including purchase of missing points',p.cashOutlay,'money'],['Cash avoided versus the matched cash alternative',p.cashSaved,'money'],['Comparison after the chosen value of existing points consumed',p.netComparison,'money']],note:'Original hypothetical single-purchase comparison in nominal CAD. The cash and reward alternatives are assumed available for the same product or journey, with identical dates, quality, cancellation terms and all other benefits; otherwise this comparison is incomplete. The reward needs the entered points and mandatory cash. Existing points are used up to the requirement; any missing points are assumed purchasable immediately in the exact required quantity at the entered all-in cents-per-point cost, with no minimum bundle, transfer delay or purchase restriction. That availability is a scenario assumption, not a program offer. The selected case uses '+p.ownedUsed.toLocaleString('en-CA')+' existing points and buys '+p.missing.toLocaleString('en-CA')+' missing points. The chosen alternative-use value applies only to existing points consumed, not to unused points or a second charge on the newly purchased points. It is an authored opportunity-value assumption, not guaranteed cash value or an accounting valuation. Implied gross redemption value is '+p.impliedCents.toFixed(3)+' cents per required point, before point-acquisition costs. No point-earning spending, annual card fee, debt interest, tax calculation, expiry, devaluation or probability is modeled. Cash avoided is a comparison with an alternative payment, not cash credited to a bank account.',charts:[
  {id:'reward-redemption-cash-outlays',type:'stackbar',title:'Cash required now differs from the number of points consumed',unit:'money',seriesNames:['Matched cash purchase','Mandatory redemption cash','Buy missing points'],rows:[{label:'Pay the matched cash price',values:[input.cashPrice,0,0]},{label:'Redeem, buying any shortfall',values:[0,input.redemptionCash,p.pointPurchase]}],evidence:'Hypothetical matched purchase alternatives',note:'Only actual modeled cash outlays appear in these bars. Using existing points consumes a separate resource and is not another cash charge in this figure. Both alternatives retain existing points that are not required for the redemption. The cash alternative also retains the existing points that the reward alternative would consume.'},
  {id:'reward-redemption-opportunity-bridge',type:'waterfall',title:'Separate cash avoided from the chosen value of existing points given up',unit:'money',rows:[{label:'Matched cash price avoided',value:input.cashPrice},{label:'Mandatory redemption cash',value:-input.redemptionCash},{label:'Purchase of missing points',value:-p.pointPurchase},{label:'Existing points: other use',value:-p.ownedValue}],totalLabel:'Net comparison value',evidence:'Hypothetical cash and opportunity-value comparison',note:'The first three steps reconcile cash avoided. The last step is the chosen value of an alternative use for existing points consumed; it is not another invoice. Purchased points are charged through their purchase price once, with no second opportunity deduction. A positive endpoint means the reward alternative is ahead under these assumptions; it is not an actual payment, guaranteed saving or recommendation to buy points.'},
  {id:'reward-redemption-value-cash-price',type:'line',title:'The cash alternative determines the implied redemption value',unit:'cents',tableUnit:'cents per required point',unitLabel:'Implied cents per required point · before acquiring points',xLabel:'Matched all-in cash alternative (CAD)',series:[{name:'Implied value from cash price less redemption cash',rows:cashRange}],evidence:'Hypothetical matched cash-price sensitivity',note:'At every point, subtract mandatory redemption cash from the alternative cash price, divide by the required points and convert CAD to cents. A higher hypothetical cash price makes the implied value larger without changing the reward. A negative value means the mandatory redemption cash alone exceeds the matched cash price. This measure ignores point-buying costs and does not replace the cash-outlay or opportunity-value comparison.'},
  {id:'reward-redemption-buy-other-use',type:'heatmap',title:'Comparison value under different point-purchase costs and other-use values',unit:'money',signed:true,compactValues:false,columns:[0,.5,1,2].map(v=>v.toFixed(1)+'¢'),rows:[0,1,2,3].map(purchaseCents=>({label:'Buy '+purchaseCents.toFixed(1)+'¢',values:[0,.5,1,2].map(alternativeCents=>rewardRedemptionCost({...input,purchaseCents,alternativeCents}).netComparison)})),evidence:'Hypothetical two-input reward sensitivity',note:'Rows replace the price paid for each missing point; columns replace the chosen other-use value of each existing point consumed. The cash alternative, redemption cash and required/owned point counts stay selected inputs. Positive values favour the reward within this model and negative values the matched cash purchase. If no points are missing, the purchase-cost rows coincide; if no existing points are used, the other-use columns coincide. None of these point values is a program quote.'}
 ]};
}
